package com.gymflow.inventory;import com.gymflow.gym.Gym;import com.gymflow.product.Product;import jakarta.persistence.*;import java.util.UUID;
@Entity @Table(name="stock_balances",uniqueConstraints=@UniqueConstraint(name="uk_stock_gym_product",columnNames={"gym_id","product_id"}))public class StockBalance{@Id @GeneratedValue(strategy=GenerationType.UUID)private UUID id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="gym_id",nullable=false)private Gym gym;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="product_id",nullable=false)private Product product;@Column(nullable=false)private int quantity=0;@Version private long version;protected StockBalance(){}public StockBalance(Gym gym,Product product){this.gym=gym;this.product=product;}public UUID getId(){return id;}public Gym getGym(){return gym;}public Product getProduct(){return product;}public int getQuantity(){return quantity;}public void setQuantity(int quantity){this.quantity=quantity;}}
